choose=ns['_choose']
app=QtWidgets.QApplication.instance() or QtWidgets.QApplication([])
real=QtTest.QTest
records=[]
def control(force_early):
 panel=QtWidgets.QWidget();layout=QtWidgets.QVBoxLayout(panel)
 panel._mode=QtWidgets.QComboBox();panel._mode.addItem('All','all');panel._mode.addItem('Selected','selected')
 panel._choose=QtWidgets.QPushButton('Choose');layout.addWidget(panel._mode);layout.addWidget(panel._choose)
 record={'forced_early_timer_delivery':force_early,'events':[]};start=time.monotonic()
 def stamp(label):record['events'].append({'event':label,'elapsed_ms':round((time.monotonic()-start)*1000,3)})
 def open_dialog():
  stamp('actual clicked slot opens modal')
  dialog=QtWidgets.QDialog(panel);box=QtWidgets.QVBoxLayout(dialog)
  rows=QtWidgets.QListWidget();box.addWidget(rows)
  item=QtWidgets.QListWidgetItem('sampler.a',rows);item.setData(QtCore.Qt.ItemDataRole.UserRole,'sampler.a');item.setFlags(item.flags()|QtCore.Qt.ItemFlag.ItemIsUserCheckable);item.setCheckState(QtCore.Qt.CheckState.Unchecked)
  buttons=QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.StandardButton.Ok|QtWidgets.QDialogButtonBox.StandardButton.Cancel)
  buttons.accepted.connect(dialog.accept);buttons.rejected.connect(dialog.reject);box.addWidget(buttons)
  dialog.exec();stamp('modal returned');dialog.deleteLater()
 panel._choose.clicked.connect(open_dialog);panel.show();app.processEvents()
 class Driver:
  @staticmethod
  def mouseClick(widget,*args,**kwargs):
   if force_early and widget is panel._choose:
    stamp('deliver pending zero timer before real mouse click')
    app.processEvents()
    record['active_modal_after_early_delivery']=app.activeModalWidget() is not None
   return real.mouseClick(widget,*args,**kwargs)
  keyClick=staticmethod(real.keyClick)
 watchdog=QtCore.QTimer();watchdog.setSingleShot(True)
 def rescue():
  stamp('independent watchdog rescues blocked modal')
  record['watchdog_fired']=True
  modal=app.activeModalWidget()
  if isinstance(modal,QtWidgets.QDialog):modal.reject()
 watchdog.timeout.connect(rescue);watchdog.start(1000)
 QtTest.QTest=Driver
 try:
  record['offered']=sorted(choose(app,panel,{'sampler.a'}))
  record['returned']='normal'
 except BaseException as e:
  record['returned']=type(e).__name__;record['error']=str(e)
 finally:
  QtTest.QTest=real;watchdog.stop();panel.close();panel.deleteLater();app.processEvents()
 record['elapsed_ms']=round((time.monotonic()-start)*1000,3)
 records.append(record)
control(False)
control(True)
assert records[0]['returned']=='normal' and not records[0].get('watchdog_fired'),records[0]
assert records[1]['returned']=='normal' and not records[1].get('watchdog_fired'),records[1]
